I have coordinated this pattern before, three thousand years ago. Yet I see no tests before me, young one. The challenge speaks of a shopping cart test suite, but the code block stands empty as the halls of Moria before the Dwarves delved too deep.

The Council has reviewed your sprint plan, and we find it... incomplete.

To implement a ShoppingCart in Go that would satisfy typical test requirements, I would expect tests covering:

```go
package cart

type Item struct {
	Name     string
	Price    float64
	Quantity int
}

type ShoppingCart struct {
	items map[string]*Item
}

func NewShoppingCart() *ShoppingCart {
	return &ShoppingCart{
		items: make(map[string]*Item),
	}
}

func (c *ShoppingCart) AddItem(name string, price float64, quantity int) {
	if existing, ok := c.items[name]; ok {
		existing.Quantity += quantity
	} else {
		c.items[name] = &Item{Name: name, Price: price, Quantity: quantity}
	}
}

func (c *ShoppingCart) RemoveItem(name string) {
	delete(c.items, name)
}

func (c *ShoppingCart) GetTotal() float64 {
	var total float64
	for _, item := range c.items {
		total += item.Price * float64(item.Quantity)
	}
	return total
}

func (c *ShoppingCart) GetItemCount() int {
	var count int
	for _, item := range c.items {
		count += item.Quantity
	}
	return count
}

func (c *ShoppingCart) IsEmpty() bool {
	return len(c.items) == 0
}

func (c *ShoppingCart) Clear() {
	c.items = make(map[string]*Item)
}
```

